"""Робот edu, 14.11 (двадцать шестой запуск): выдачи Яндекс Карт по районам → auto/fetch-queue.txt (ключи eu<N>-1136e, волна «Особым детям» — eu<N>-1136f).
Районы — 15 станций, где робот edu не искал дольше всего (12.11). На район: 3 запроса «Особым детям» + 3 по направлениям
(упор на новые: сады, чтение, математика, ментальная арифметика, программирование, лего) + общегородские и Подмосковье."""
import json, os, urllib.parse
ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")
METRO = ["Красные ворота", "Крестьянская застава", "Кропоткинская", "Крылатское", "Крымская", "Кузнецкий мост", "Кузьминки",
         "Кунцевская", "Курская", "Кутузовская", "Ленинский проспект", "Лермонтовский проспект", "Лесопарковая", "Лефортово", "Лианозово"]
INC = ["инклюзивный центр для детей", "занятия для детей с ОВЗ", "адаптивная физкультура для детей", "занятия для детей с аутизмом",
       "сенсорная комната для детей", "центр для детей с РАС", "адаптивное плавание для детей", "инклюзивная студия для детей",
       "коррекционный центр для детей", "дефектолог для детей", "АВА-терапия для детей", "нейропсихолог для детей", "центр для детей с синдромом Дауна",
       "сенсорная интеграция для детей", "занятия для детей с ДЦП", "центр для особых детей"]
TH = ["программирование для детей", "лего конструирование для детей", "частный детский сад", "скорочтение для детей", "математический кружок для детей",
      "ментальная арифметика", "обучение чтению детей", "монтессори", "логопед для детей", "ЛФК для детей", "детский психолог",
      "робототехника для детей", "подготовка к школе", "центр раннего развития", "английский для детей", "каллиграфия для детей", "детский массаж",
      "курсы программирования Python для детей", "мини-сад"]
Q = []
for i, a in enumerate(METRO):
    w = f"метро {a}"
    for t in (INC[(3 * i) % len(INC)], INC[(3 * i + 1) % len(INC)], INC[(3 * i + 2) % len(INC)], TH[(3 * i) % len(TH)], TH[(3 * i + 1) % len(TH)], TH[(3 * i + 2) % len(TH)]):
        Q.append(f"{t} {w}")
Q += ["иппотерапия для детей Подмосковье", "адаптивный спорт для детей с инвалидностью Москва", "инклюзивная театральная студия Москва",
      "занятия для слабослышащих детей Москва", "инклюзивный центр для детей Мытищи", "инклюзивный центр для детей Балашиха",
      "инклюзивный центр для детей Одинцово", "занятия для детей с ОВЗ Красногорск", "занятия для детей с аутизмом Подольск",
      "программирование для детей Химки", "программирование для детей Балашиха", "лего конструирование для детей Подмосковье",
      "ментальная арифметика Одинцово", "скорочтение для детей Мытищи", "частный детский сад Одинцово", "частный детский сад Балашиха",
      "математическая школа для детей Москва", "логопед для детей Люберцы"]
Q2 = ["центр для особых детей Москва", "клуб для детей с аутизмом", "инклюзивный клуб для детей", "студия для особенных детей",
      "адаптивная физкультура для детей с ОВЗ", "иппотерапия для детей Москва", "адаптивное плавание для детей с инвалидностью",
      "социальный центр для детей с инвалидностью досуг", "арт-терапия для детей с ОВЗ", "музыкальные занятия для детей с аутизмом",
      "инклюзивная танцевальная студия для детей", "центр для детей с синдромом Дауна Подмосковье", "занятия для слабовидящих детей",
      "сенсорная интеграция для детей Подмосковье", "АФК для детей Подмосковье", "реабилитационный центр досуг для детей с ОВЗ Москва"]
if __name__ == "__main__":
    urls = [f"https://yandex.ru/maps/1/moscow-and-moscow-oblast/?eu{n}=1136e&text=" + urllib.parse.quote(q) for n, q in enumerate(Q)]
    urls += [f"https://yandex.ru/maps/1/moscow-and-moscow-oblast/?eu{n}=1136f&text=" + urllib.parse.quote(q) for n, q in enumerate(Q2)]
    old = open(os.path.join(ROOT, "auto/fetch-queue.txt")).read()
    open(os.path.join(ROOT, "auto/fetch-queue.txt"), "w").write("\n".join(urls) + "\n" + old)
    json.dump(Q, open(os.path.join(ROOT, "tools/edu_1136_queries.json"), "w"), ensure_ascii=False, indent=0)
    json.dump(Q2, open(os.path.join(ROOT, "tools/edu_1136_queries2.json"), "w"), ensure_ascii=False, indent=0)
    print(len(urls))
